layer.css:
[data-ryt="pitch"] { color: var(--ryt-text); border-left: 2px solid rgb(111, 106, 91); border-radius: 0px; font-family: var(--ryt-font-body); font-size: 18.4px; font-weight: 400; font-style: italic; line-height: 1.74; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 1.6px; padding-right: 0px; padding-bottom: 1.6px; padding-left: 20px; transition: all; border-top: none; border-right: none; border-bottom: none }
[data-ryt="footer"] { color: var(--ryt-muted); border-top: 1px solid rgba(68, 62, 52, 0.15); font-style: normal; letter-spacing: normal; text-transform: none }
article[data-ryt="rec-card"] { border-bottom: 1px solid rgba(68, 62, 52, 0.15); border-radius: 0px; transition: color 0.16s, background-color 0.16s; border-top: none; border-right: none; border-left: none }
[data-ryt="credit"] a, [data-ryt="review"] a, [data-ryt="bio"] a { color: var(--ryt-accent); border-radius: 0px; font-weight: 400; font-style: normal; letter-spacing: normal; text-transform: none; text-decoration-line: underline; text-decoration-style: solid; text-decoration-color: rgba(50, 80, 110, 0.4); text-decoration-thickness: 1.104px; text-underline-offset: 3.312px; transition: color 0.16s, text-decoration-color 0.16s, border-color 0.16s, background-color 0.16s, transform 0.16s }
[data-ryt="hero"] h1 { color: var(--ryt-text); font-family: var(--ryt-font-heading); font-size: 56px; font-weight: 500; font-style: normal; line-height: 1.02; letter-spacing: -1.56px; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="section"] > h2 { color: var(--ryt-text); border-radius: 0px; font-family: var(--ryt-font-heading); font-weight: 500; font-style: normal; line-height: 1.05; letter-spacing: -0.9728px; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="brand"] { color: var(--ryt-text); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 40px; font-weight: 500; font-style: normal; line-height: 0.95; letter-spacing: -1.536px; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="category"], [data-ryt="tags"] li { color: rgb(63, 94, 88); border-radius: 0px; font-family: var(--ryt-font-body); font-weight: 700; font-style: normal; line-height: 1.65; letter-spacing: 1.312px; text-transform: uppercase; text-decoration-style: solid; text-decoration-color: rgb(63, 94, 88); text-decoration-thickness: auto; text-underline-offset: 2.88px; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 0px; transition: all }
[data-ryt="review"] { color: rgb(81, 76, 69); font-family: var(--ryt-font-body); font-size: 17.76px; font-weight: 400; font-style: normal; line-height: 1.55; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(81, 76, 69); text-decoration-thickness: auto; text-underline-offset: 2.88px; transition: all }
[data-ryt="credit"], [data-ryt="eyebrow"] { color: var(--ryt-muted); font-family: var(--ryt-font-body); font-size: 12px; font-weight: 700; font-style: normal; line-height: 1.65; letter-spacing: 1.44px; text-transform: uppercase; text-decoration-style: solid; text-decoration-color: var(--ryt-muted); text-decoration-thickness: auto; text-underline-offset: 2.88px; transition: all }
[data-ryt="rec-card"] [data-ryt="title"] a { color: var(--ryt-text); border-bottom: 1px solid rgba(68, 62, 52, 0.15); border-radius: 0px; font-family: var(--ryt-font-body); font-weight: 400; font-style: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: 2.88px; transition: color 0.16s, background-color 0.16s; border-top: none; border-right: none; border-left: none }
[data-ryt="rec-card"] [data-ryt="title"] { color: var(--ryt-text); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 24.32px; font-weight: 500; font-style: normal; line-height: 1.1; letter-spacing: -0.29184px; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: 2.88px; transition: all }
[data-ryt="rec-card"] [data-ryt="title"]:hover { color: #3f5e58 }
[data-ryt="rec-card"] [data-ryt="title"] a:hover { color: #3f5e58; text-decoration-color: initial; color: inherit; transform: none; background-image: initial; background-color: initial; box-shadow: none }
[data-ryt="category"]::after, [data-ryt="tags"] li::after { content: "→"; display: block; width: 15.0781px; height: 13.7812px; margin-left: 4px; color: rgb(63, 94, 88); background-size: auto; background-position: 0% 0%; background-repeat: repeat; border-radius: 0px; font-family: var(--ryt-font-body); font-size: 13.776px; font-weight: 700; font-style: normal; line-height: 1; letter-spacing: 1.312px; text-transform: uppercase; text-decoration-style: solid; text-decoration-color: rgb(63, 94, 88); text-decoration-thickness: auto; text-underline-offset: 2.88px; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 0px; transition: transform 0.16s; -webkit-text-fill-color: rgb(63, 94, 88) }
[data-ryt="credit"] a:hover, [data-ryt="review"] a:hover, [data-ryt="bio"] a:hover { color: #3f5e58; text-decoration-color: initial }
article[data-ryt="rec-card"]:hover { color: #3f5e58; text-decoration-color: initial; color: inherit; transform: none; background-image: initial; background-color: initial; box-shadow: none }
